const __aivicBundle_20_sendDailyReportAndNotify = (() => {
  async function sendDailyReportAndNotify(input: {
    user_id?: string;
    email_address?: string;
    user_name?: string;
    yesterday_work?: string;
    today_plan?: string;
    current_issue?: string;
    submission_datetime?: string;
  }): Promise<{ report_id: string; status: string }> {
    const { randomUUID } = await import('crypto');
  
    const reportId = `report_${randomUUID()}`;
  
    const emailPayload = {
      recipient: input.email_address,
      subject: '朝会報告 - 確認メール',
      body: `
  日報確認メール
  
  送信者: ${input.user_name}
  送信日時: ${input.submission_datetime}
  
  【昨日の実績】
  ${input.yesterday_work}
  
  【本日の予定】
  ${input.today_plan}
  
  【課題・懸念事項】
  ${input.current_issue}
      `.trim(),
    };
  
    const response = await fetch('/api/send-mail', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(emailPayload),
    });
  
    if (!response.ok) {
      throw new Error(`Failed to send confirmation email: ${response.status}`);
    }
  
    return {
      report_id: reportId,
      status: 'sent',
    };
  }
  return { sendDailyReportAndNotify };
})();
export const sendDailyReportAndNotify = __aivicBundle_20_sendDailyReportAndNotify.sendDailyReportAndNotify;
