const __aivicBundle_24_sendConfirmationEmailWithReport = (() => {
  async function sendConfirmationEmailWithReport(report_data: {
    user_id?: string;
    user_name?: string;
    user_email?: string;
    yesterday_work?: string;
    today_plan?: string;
    challenge?: string;
    report_date?: string;
  }): Promise<{ success: boolean; message: string; sent_to: Array<{ email: string }> }> {
    const {
      user_id,
      user_name,
      user_email,
      yesterday_work,
      today_plan,
      challenge,
      report_date,
    } = report_data;
  
    const email_body = buildEmailBody(
      user_name,
      yesterday_work,
      today_plan,
      challenge,
      report_date
    );
  
    const request_body = {
      user_id,
      user_name,
      user_email,
      yesterday_work,
      today_plan,
      challenge,
      report_date,
      email_body,
    };
  
    const response = await fetch('/api/send-confirmation-email', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(request_body),
    });
  
    const result = await response.json();
  
    return {
      success: result.success,
      message: result.message,
      sent_to: result.sent_to.map((email: string) => ({ email })),
    };
  }
  
  function buildEmailBody(
    user_name?: string,
    yesterday_work?: string,
    today_plan?: string,
    challenge?: string,
    report_date?: string
  ): string {
    const lines: string[] = [];
  
    if (report_date) {
      lines.push(`報告日: ${report_date}`);
    }
  
    if (user_name) {
      lines.push(`報告者: ${user_name}`);
    }
  
    if (yesterday_work) {
      lines.push(`昨日の実績: ${yesterday_work}`);
    }
  
    if (today_plan) {
      lines.push(`本日の予定: ${today_plan}`);
    }
  
    if (challenge) {
      lines.push(`抱えている課題: ${challenge}`);
    }
  
    return lines.join('\n');
  }
  return { sendConfirmationEmailWithReport };
})();
